package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class UTF8JsonGenerator_writeBinary_TriageGen1Test {

    private ByteArrayOutputStream out;
    private IOContext context;
    private UTF8JsonGenerator generator;
    private static final Base64Variant DEFAULT_VARIANT = Base64Variant.Base64Encoding;

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        context = new IOContext();
        // Using the constructor provided in the prompt
        generator = new UTF8JsonGenerator(context, 0, null, out);
    }

    @After
    public void tearDown() throws IOException {
        generator.close();
    }

    /**
     * Tests the branch where dataLength < 0 (unknown length).
     * This verifies the call to _writeBinary(b64variant, data, encodingBuffer).
     */
    @Test
    public void testWriteBinary_UnknownLength() throws IOException {
        byte[] inputData = {0x01, 0x02, 0x03, 0x04};
        InputStream is = new ByteArrayInputStream(inputData);

        // dataLength = -1 triggers the "unknown length" branch
        int bytesWritten = generator.writeBinary(DEFAULT_VARIANT, is, -1);

        assertEquals(4, bytesWritten);
        String result = out.toString();
        // Check if wrapped in quotes and is valid base64
        // 01 02 03 04 in Base64 is AQIDBA==
        assertEquals("\"AQIDBA==\"", result);
    }

    /**
     * Tests the branch where dataLength >= 0 and matches the input stream exactly.
     * This verifies the call to _writeBinary(b64variant, data, encodingBuffer, dataLength).
     */
    @Test
    public void testWriteBinary_ExactLength() throws IOException {
        byte[] inputData = {0x01, 0x02, 0x03, 0x04};
        InputStream is = new ByteArrayInputStream(inputData);
        int expectedLength = 4;

        int bytesWritten = generator.writeBinary(DEFAULT_VARIANT, is, expectedLength);

        assertEquals(expectedLength, bytesWritten);
        String result = out.toString();
        assertEquals("\"AQIDBA==\"", result);
    }

    /**
     * Tests the error branch where dataLength > actual bytes available.
     * This verifies the 'if (missing > 0)' branch and the _reportError call.
     */
    @Test(expected = IOException.class)
    public void testWriteBinary_TooFewBytes() throws IOException {
        byte[] inputData = {0x01, 0x02}; // Only 2 bytes
        InputStream is = new ByteArrayInputStream(inputData);
        int expectedLength = 4; // But we claim 4

        // This should trigger _reportError via IOException
        generator.writeBinary(DEFAULT_VARIANT, is, expectedLength);
    }

    /**
     * Tests the buffer flushing logic.
     * By writing a large amount of data, we force _outputTail >= _outputEnd,
     * triggering _flushBuffer() at the start and end of the method.
     */
    @Test
    public void testWriteBinary_TriggersFlush() throws IOException {
        // Create a large payload to exceed default buffer size
        byte[] largeData = new byte[2048];
        for (int i = 0; i < largeData.length; i++) {
            largeData[i] = (byte) (i % 256);
        }
        InputStream is = new ByteArrayInputStream(largeData);

        // We use a known length to avoid the "unknown length" branch for this specific test
        int bytesWritten = generator.writeBinary(DEFAULT_VARIANT, is, largeData.length);

        assertEquals(largeData.length, bytesWritten);

        // Verify output starts and ends with quotes
        byte[] output = out.toByteArray();
        assertEquals((byte) '"', output[0]);
        assertEquals((byte) '"', output[output.length - 1]);
    }

    /**
     * Tests the behavior with an empty InputStream and 0 length.
     */
    @Test
    public void testWriteBinary_EmptyStream() throws IOException {
        byte[] inputData = new byte[0];
        InputStream is = new ByteArrayInputStream(inputData);

        int bytesWritten = generator.writeBinary(DEFAULT_VARIANT, is, 0);

        assertEquals(0, bytesWritten);
        assertEquals("\"\"", out.toString());
    }
}
